<template><div class="matches-page page-animate"><div class="wrap"><div class="page-head professional-head"><span class="eyebrow">Football centre</span><h1>Football Matches & Odds</h1><p class="muted">Fixtures, live scores, prices and match research in one place.</p></div><div class="toolbar pro-tabs"><button v-for="x in tabs" :key="x.v" class="filter-btn" :class="{selected:tab===x.v}" @click="tab=x.v">{{x.l}}</button><RouterLink to="/dropping-odds" class="drop-link">↘ Dropping odds</RouterLink></div><div v-if="loading" class="empty">Loading matches…</div><div v-else-if="error" class="error">{{error}} <button class="ghost" @click="load">Try again</button></div><div v-else class="match-board"><RouterLink v-for="m in matches" :key="m._id" :to="matchPath(m._id)" class="match-row"><div class="row-league"><span>{{m.leagueId?.name||'Football'}}</span><span :class="['status-chip',m.status]">{{m.status==='live'?'● LIVE':m.status}}</span></div><div class="row-teams"><div class="row-team"><TeamLogo :src="m.homeTeamId?.logo" :name="m.homeTeamId?.name" size="sm"/><b>{{m.homeTeamId?.name||'Home'}}</b></div><div class="row-score"><strong v-if="m.status==='live'||m.status==='finished'">{{m.homeScore}} - {{m.awayScore}}</strong><strong v-else>{{time(m.kickoff)}}</strong><small>{{m.status==='scheduled'?'Kick-off':''}}</small></div><div class="row-team away"><b>{{m.awayTeamId?.name||'Away'}}</b><TeamLogo :src="m.awayTeamId?.logo" :name="m.awayTeamId?.name" size="sm"/></div></div><div v-if="m.odds?.length" class="mini-odds"><span v-for="o in m.odds.slice(0,3)" :key="o._id"><b>{{o.label}}</b> {{Number(o.value).toFixed(2)}}</span></div><div class="row-cta">View match →</div></RouterLink><div v-if="!matches.length" class="empty">No matches found.</div></div></div></div></template><script setup lang="ts">import {onMounted,ref,watch} from 'vue';import {RouterLink} from 'vue-router';import {api} from '../services/api';import TeamLogo from '../components/TeamLogo.vue';const tabs=[{v:'today',l:'Today'},{v:'live',l:'Live'},{v:'finished',l:'Results'},{v:'scheduled',l:'Upcoming'}],tab=ref('today'),matches=ref<any[]>([]),loading=ref(false),error=ref('');const time=(v:string)=>new Date(v).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});const matchPath=(id:string)=>`/matches/${id}`;async function load(){loading.value=true;error.value='';try{const d=tab.value==='today'?await api.get('/matches/today'):tab.value==='live'?await api.get('/matches/live'):await api.get(`/matches?status=${tab.value}&limit=100`);matches.value=d.data||[]}catch(e:any){error.value=e.message||'Unable to load matches.'}finally{loading.value=false}}watch(tab,load);onMounted(load)</script>